-- TASK-214 RV: 8 original Y2 and 8 Y3, review only. Source V2 chapter 2.
BEGIN;
DO $$BEGIN IF (SELECT count(*) FROM public.questions WHERE source_reference LIKE 'GV2:GV-%')<>300 THEN RAISE EXCEPTION 'TASK-214 prerequisite 300 questions missing'; END IF; END$$;
ON CONFLICT(id) DO NOTHING;
ON CONFLICT(id) DO NOTHING;
ON CONFLICT(question_id) DO NOTHING;
DO $$BEGIN IF (SELECT count(*) FROM public.questions WHERE source_reference LIKE 'Grafika va veb-texnologiyalar V2, bob 2%GV2-EXT-RV-%' AND status='review')<>16 THEN RAISE EXCEPTION 'TASK-214 RV count mismatch'; END IF; END$$;
COMMIT;
